#[cfg(test)]
mod tests {
    use super::*;

    fn hex_rgba(h: &str) -> u32 {
        let h = h.trim_start_matches('#');
        u32::from_str_radix(&if h.len() == 6 { format!("{h}FF") } else { h.to_string() }, 16).unwrap()
    }

    /// Every token of `design/tokens.src.json` is a constant here with the same values.
    #[test]
    fn tokens_match_design_json() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../design/tokens.src.json");
        let json: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        let mut colors = 0;
        let mut check = |name: &str, dark: &str, light: &str| {
            let t = ALL_COLORS.iter().find(|(n, _)| *n == name).unwrap_or_else(|| panic!("missing {name}")).1;
            assert_eq!(t.rgba(true), hex_rgba(dark), "{name} dark");
            assert_eq!(t.rgba(false), hex_rgba(light), "{name} light");
            colors += 1;
        };
        for c in json["colors"].as_array().unwrap() {
            check(c["name"].as_str().unwrap(), c["dark"].as_str().unwrap(), c["light"].as_str().unwrap());
        }
        for (name, s) in json["shadow"].as_object().unwrap() {
            check(name, s["dark"].as_str().unwrap(), s["light"].as_str().unwrap());
        }
        assert_eq!(colors, ALL_COLORS.len());
        let mut numbers = 0;
        let mut check = |name: &str, value: f64| {
            let s = ALL_NUMBERS.iter().find(|(n, _)| *n == name).unwrap_or_else(|| panic!("missing {name}")).1;
            assert!((f64::from(s) - value).abs() < 1e-6, "{name}: {s} != {value}");
            numbers += 1;
        };
        for group in ["size", "spacing", "radius", "motion", "alpha"] {
            for (name, e) in json[group].as_object().unwrap() {
                match e.get("value") {
                    Some(v) => check(name, v.as_f64().unwrap()),
                    None => {
                        check(&format!("{name}-dark"), e["dark"].as_f64().unwrap());
                        check(&format!("{name}-light"), e["light"].as_f64().unwrap());
                    }
                }
            }
        }
        for t in json["type"].as_array().unwrap() {
            check(t["name"].as_str().unwrap(), t["size"].as_f64().unwrap());
        }
        assert_eq!(numbers, ALL_NUMBERS.len());
    }
}
